import { Request, Response, NextFunction } from "express";
import { IAuthService } from "../../interfaces/auth/IAuthService";
import { signupSchema, loginSchema } from "../../dto/auth/auth.dto";
import { sendSuccess } from "../../shared/utils/response";
import { Messages } from "../../shared/constants/messages";
import { StatusCodes } from "../../shared/constants/statusCodes";
import { env } from "../../config/env";
import { Role } from "../../shared/enums/role.enum";

export class AuthController {
  constructor(private readonly service: IAuthService) {}

  async signup(req: Request, res: Response, next: NextFunction) {
    try {
      const dto = signupSchema.parse(req.body);
      const result = await this.service.signup(dto);
      sendSuccess(res, result, Messages.USER_CREATED, StatusCodes.CREATED);
    } catch (err) { next(err); }
  }

  async login(req: Request, res: Response, next: NextFunction) {
    try {
      const dto = loginSchema.parse(req.body);
      const result = await this.service.login(dto, false, Role.USER);
      sendSuccess(res, result, Messages.LOGIN_SUCCESS);
    } catch (err) { next(err); }
  }

  async adminLogin(req: Request, res: Response, next: NextFunction) {
    try {
      const dto = loginSchema.parse(req.body);
      const result = await this.service.login(dto, false, Role.ADMIN);
      sendSuccess(res, result, Messages.LOGIN_SUCCESS);
    } catch (err) { next(err); }
  }

  async verifyOtp(req: Request, res: Response, next: NextFunction) {
    try {
      const { email, otp } = req.body;
      const result = await this.service.verifyOtp(email, otp);
      sendSuccess(res, result, result.message);
    } catch (err) { next(err); }
  }

  async resendOtp(req: Request, res: Response, next: NextFunction) {
    try {
      const { email, phone } = req.body;
      const result = await this.service.resendOtp(email, phone);
      sendSuccess(res, result, result.message);
    } catch (err) { next(err); }
  }

  async forgotPassword(req: Request, res: Response, next: NextFunction) {
    try {
      const { email } = req.body;
      const result = await this.service.forgotPassword(email);
      sendSuccess(res, result, result.message);
    } catch (err) { next(err); }
  }

  async resetPassword(req: Request, res: Response, next: NextFunction) {
    try {
      const { email, otp, newPassword } = req.body;
      const result = await this.service.resetPassword(email, otp, newPassword);
      sendSuccess(res, result, result.message);
    } catch (err) { next(err); }
  }

  async refreshToken(req: Request, res: Response, next: NextFunction) {
    try {
      const { token } = req.body;
      const result = await this.service.refreshToken(token);
      sendSuccess(res, result, Messages.TOKEN_REFRESHED);
    } catch (err) { next(err); }
  }

  async logout(req: Request, res: Response, next: NextFunction) {
    try {
      const { token } = req.body;
      await this.service.logout(token);
      sendSuccess(res, null, Messages.LOGOUT_SUCCESS);
    } catch (err) { next(err); }
  }

  async googleCallback(req: Request, res: Response, next: NextFunction) {
    try {
      if (!req.user) {
        return res.redirect(`${env.FRONTEND_URL}/login?oauthError=${Messages.AUTH_FAILED}`);
      }
      const user = req.user as unknown as { email: string };
      const result = await this.service.login({ email: user.email, password: "" }, true, Role.USER);
      res.redirect(`${env.FRONTEND_URL}/google-callback?accessToken=${result.accessToken}&refreshToken=${result.refreshToken}`);
    } catch (error) {
      const message = error instanceof Error ? error.message : "AuthenticationFailed";
      const code = message === Messages.CROSS_PLATFORM_LOGIN_BLOCKED ? Messages.WRONG_PLATFORM : Messages.AUTH_FAILED;
      res.redirect(`${env.FRONTEND_URL}/login?oauthError=${code}`);
    }
  }
}

import { Response, NextFunction } from "express";
import { AuthRequest } from "../../shared/interfaces/AuthRequest";
import { sendSuccess } from "../../shared/utils/response";
import { IBookingService } from "../../interfaces/booking/IBookingService";
import { createBookingSchema, rescheduleBookingSchema, cancelBookingSchema, bookingQuerySchema, updateStatusSchema, adminBookingQuerySchema } from "../../dto/booking/booking.dto";

export class BookingController {
  constructor(private readonly service: IBookingService) {}

  async create(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const dto = createBookingSchema.parse(req.body);
      const data = await this.service.createBooking(req.user!.id, dto);
      sendSuccess(res, data, "Booking created successfully", 201);
    } catch (err) { next(err); }
  }

  async getMyBookings(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const query = bookingQuerySchema.parse(req.query);
      const data = await this.service.getUserBookings(req.user!.id, query);
      sendSuccess(res, data, "Bookings fetched");
    } catch (err) { next(err); }
  }

  async getProviderBookings(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const query = bookingQuerySchema.parse(req.query);
      const data = await this.service.getProviderBookings(req.user!.id, query);
      sendSuccess(res, data, "Bookings fetched");
    } catch (err) { next(err); }
  }

  async getById(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const data = await this.service.getBookingById(req.params.id as string, req.user!.id);
      sendSuccess(res, data, "Booking fetched");
    } catch (err) { next(err); }
  }

  async reschedule(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const dto = rescheduleBookingSchema.parse(req.body);
      const data = await this.service.reschedule(req.params.id as string, req.user!.id, dto);
      sendSuccess(res, data, "Booking rescheduled");
    } catch (err) { next(err); }
  }

  async updateStatus(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const { status } = updateStatusSchema.parse(req.body);
      const data = await this.service.updateStatus(req.params.id as string, req.user!.id, status as any);
      sendSuccess(res, data, "Booking status updated");
    } catch (err) { next(err); }
  }

  async cancel(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const dto = cancelBookingSchema.parse(req.body);
      const data = await this.service.cancel(req.params.id as string, req.user!.id, dto.reason);
      sendSuccess(res, data, "Booking cancelled");
    } catch (err) { next(err); }
  }

  async adminGetAll(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const { status, search, page, limit } = adminBookingQuerySchema.parse(req.query);
      const data = await this.service.getAllBookings(status as any, search, page, limit);
      sendSuccess(res, data, "Bookings fetched");
    } catch (err) { next(err); }
  }
}

import { Response, NextFunction } from "express";
import { AuthRequest } from "../../shared/interfaces/AuthRequest";
import { sendSuccess } from "../../shared/utils/response";
import { IMessagingService } from "../../interfaces/messaging/IMessagingService";
import { Role } from "../../shared/enums/role.enum";
import {
  createConversationSchema,
  sendMessageSchema,
  messageQuerySchema,
  conversationQuerySchema,
  SenderRole,
} from "../../dto/messaging/messaging.dto";

export class MessagingController {
  constructor(private readonly service: IMessagingService) {}

  async getOrCreate(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const dto = createConversationSchema.parse(req.body);
      const userId = req.user!.role === Role.USER ? req.user!.id : req.body.userId;
      const provId = req.user!.role === Role.PROVIDER ? req.user!.id : dto.providerId;
      const conv = await this.service.getOrCreateConversation(userId, provId, dto.serviceId, dto.bookingId);
      sendSuccess(res, conv, "Conversation ready");
    } catch (e) { next(e); }
  }

  async getConversations(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const query = conversationQuerySchema.parse(req.query);
      const role = req.user!.role;
      const data = role === Role.PROVIDER
        ? await (this.service as any).getProviderConversationsWithPagination(req.user!.id, query.search, query.page, query.limit)
        : await (this.service as any).getUserConversationsWithPagination(req.user!.id, query.search, query.page, query.limit);
      sendSuccess(res, data, "Conversations fetched");
    } catch (e) { next(e); }
  }

  async getMessages(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const { page, limit } = messageQuerySchema.parse(req.query);
      const data = await this.service.getMessages(req.params.id as string, req.user!.id, page, limit);
      sendSuccess(res, data, "Messages fetched");
    } catch (e) { next(e); }
  }

  async sendMessage(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const { content } = sendMessageSchema.parse(req.body);
      const senderRole: SenderRole = req.user!.role === Role.PROVIDER ? "provider" : "user";
      const msg = await this.service.sendMessage(req.params.id as string, req.user!.id, senderRole, content);
      sendSuccess(res, msg, "Message sent", 201);
    } catch (e) { next(e); }
  }

  async markRead(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const role: SenderRole = req.user!.role === Role.PROVIDER ? "provider" : "user";
      await this.service.markRead(req.params.id as string, req.user!.id, role);
      sendSuccess(res, null, "Marked as read");
    } catch (e) { next(e); }
  }

  async getUnreadCount(req: AuthRequest, res: Response, next: NextFunction) {
    try {
      const role: SenderRole = req.user!.role === Role.PROVIDER ? "provider" : "user";
      const count = await this.service.getUnreadCount(req.user!.id, role);
      sendSuccess(res, { count }, "Unread count");
    } catch (e) { next(e); }
  }
}

import { Response, NextFunction } from "express";
