import { ConversationModel, IConversation, MessageModel, IMessage } from "../models/messaging.model";
import {
  IConversationRepository,
  IMessageRepository,
} from "../interfaces/messaging/IMessagingRepository";

import { SenderRole } from "../dto/messaging/messaging.dto";

export interface ConversationListResult {
  items: IConversation[];
  total: number;
}

// ── Conversation Repository ───────────────────────────────────────────────────
// Note: messaging uses two separate models (Conversation + Message), so we
// do NOT extend BaseRepository here — we implement the interfaces directly.

export class ConversationRepository implements IConversationRepository {


  async findByParticipants(userId: string, providerId: string): Promise<IConversation | null> {
    return ConversationModel.findOne({ userId, providerId }).lean() as Promise<IConversation | null>;
  }

  async create(data: Partial<IConversation>): Promise<IConversation> {
    return ConversationModel.create(data) as Promise<IConversation>;
  }

  async findById(id: string): Promise<IConversation | null> {
    return ConversationModel.findById(id).lean() as Promise<IConversation | null>;
  }

  async findByUser(userId: string): Promise<IConversation[]> {
    return ConversationModel.find({ userId })
      .populate("providerId", "name businessName headshot")
      .populate("serviceId", "name images")
      .sort({ lastMessageAt: -1 })
      .lean() as Promise<IConversation[]>;
  }

  async findByUserWithPagination(
    userId: string,
    search?: string,
    page = 1,
    limit = 20
  ): Promise<ConversationListResult> {
    const filter: Record<string, any> = { userId };
    if (search) {
      filter.$or = [
        { "providerId.name": { $regex: search, $options: "i" } },
        { "providerId.businessName": { $regex: search, $options: "i" } },
        { lastMessage: { $regex: search, $options: "i" } },
      ];
    }
    const skip = (page - 1) * limit;
    const [items, total] = await Promise.all([
      ConversationModel.find(filter)
        .populate("providerId", "name businessName headshot")
        .populate("serviceId", "name images")
        .sort({ lastMessageAt: -1 })
        .skip(skip)
        .limit(limit)
        .lean() as Promise<IConversation[]>,
      ConversationModel.countDocuments(filter),
    ]);
    return { items, total };
  }

  async findByProvider(providerId: string): Promise<IConversation[]> {
    return ConversationModel.find({ providerId })
      .populate("userId", "name email profileImage")
      .populate("serviceId", "name images")
      .populate("bookingId", "date startTime bookingStatus")
      .sort({ lastMessageAt: -1 })
      .lean() as Promise<IConversation[]>;
  }

  async findByProviderWithPagination(
    providerId: string,
    search?: string,
    page = 1,
    limit = 20
  ): Promise<ConversationListResult> {
    const filter: Record<string, any> = { providerId };
    if (search) {
      filter.$or = [
        { "userId.name": { $regex: search, $options: "i" } },
        { "userId.email": { $regex: search, $options: "i" } },
        { lastMessage: { $regex: search, $options: "i" } },
      ];
    }
    const skip = (page - 1) * limit;
    const [items, total] = await Promise.all([
      ConversationModel.find(filter)
        .populate("userId", "name email profileImage")
        .populate("serviceId", "name images")
        .populate("bookingId", "date startTime bookingStatus")
        .sort({ lastMessageAt: -1 })
        .skip(skip)
        .limit(limit)
        .lean() as Promise<IConversation[]>,
      ConversationModel.countDocuments(filter),
    ]);
    return { items, total };
  }

  async updateLastMessage(
    id: string,
    content: string,
    senderRole: SenderRole
  ): Promise<IConversation | null> {
    const inc = senderRole === "user" ? { providerUnread: 1 } : { userUnread: 1 };
    return ConversationModel.findByIdAndUpdate(
      id,
      { lastMessage: content, lastMessageAt: new Date(), $inc: inc },
      { new: true }
    ).lean() as Promise<IConversation | null>;
  }

  async resetUnreadCount(id: string, role: SenderRole): Promise<void> {
    const update = role === "user" ? { userUnread: 0 } : { providerUnread: 0 };
    await ConversationModel.findByIdAndUpdate(id, update);
  }

  async sumUnreadByUser(userId: string): Promise<number> {
    const result = await ConversationModel.aggregate([
      { $match: { userId: { $eq: userId } } },
      { $group: { _id: null, total: { $sum: "$userUnread" } } },
    ]);
    return result[0]?.total ?? 0;
  }

  async sumUnreadByProvider(providerId: string): Promise<number> {
    const result = await ConversationModel.aggregate([
      { $match: { providerId: { $eq: providerId } } },
      { $group: { _id: null, total: { $sum: "$providerUnread" } } },
    ]);
    return result[0]?.total ?? 0;
  }
}

// ── Message Repository ────────────────────────────────────────────────────────

export class MessageRepository implements IMessageRepository {
  async create(data: Partial<IMessage>): Promise<IMessage> {
    return MessageModel.create(data) as Promise<IMessage>;
  }

  async findByConversation(
    conversationId: string,
    page = 1,
    limit = 50
  ): Promise<IMessage[]> {
    const messages = await MessageModel.find({ conversationId })
      .sort({ createdAt: -1 })
      .skip((page - 1) * limit)
      .limit(limit)
      .lean();
    return messages.reverse() as IMessage[];
  }

  async markReadByRecipient(conversationId: string, recipientId: string): Promise<void> {
    await MessageModel.updateMany(
      { conversationId, senderId: { $ne: recipientId }, isRead: false },
      { isRead: true }
    );
  }
}

import { IAdminRepository } from "../interfaces/admin/IAdminRepository";
import { IAdminService } from "../interfaces/admin/IAdminService";
import { Messages } from "../shared/constants/messages";
import { StatusCodes } from "../shared/constants/statusCodes";
import { Status } from "../shared/enums/status.enum";
import { Role } from "../shared/enums/role.enum";
import { ApplicationStatus } from "../shared/enums/application-status.enum";
import { RejectionReasonCode, REJECTION_REASON_LABELS } from "../shared/enums/rejection-reason.enum";
import { NotFoundError, BadRequestError, ForbiddenError } from "../shared/errors/HttpErrors";

export class AdminService implements IAdminService {
  constructor(private  repo: IAdminRepository) {}

  async getDashboardStats() {
    const [totalUsers, totalProviders, pendingApplications] = await Promise.all([
      this.repo.countUsers(),
      this.repo.countProviderAccounts({ applicationStatus: ApplicationStatus.APPROVED }),
      this.repo.countProviderAccounts({ applicationStatus: ApplicationStatus.PENDING }),
    ]);
    return { totalUsers, totalProviders, pendingApplications };
  }

  async viewApplications(statusFilter?: string) {
    const query: Record<string, string> = {};
    if (statusFilter) query.applicationStatus = statusFilter;
    return this.repo.findProviderAccounts(query);
  }

  async viewUsers(search?: string, statusFilter?: string) {
    const query: Record<string, unknown> = { role: Role.USER };
    if (search) {
      query.$or = [
        { name: { $regex: search, $options: "i" } },
        { email: { $regex: search, $options: "i" } },
      ];
    }
    if (statusFilter) query.status = statusFilter;
    return this.repo.findUsers(query);
  }

  async blockUser(userId: string) {
    const user = await this.repo.findUserById(userId);
    if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);
    if (user.role === Role.ADMIN) throw new ForbiddenError(Messages.CANNOT_BLOCK_ADMIN);
    return this.repo.updateUserById(userId, { status: Status.BLOCKED });
  }

  async unblockUser(userId: string) {
    const user = await this.repo.findUserById(userId);
    if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);
    if (user.role === Role.ADMIN) throw new ForbiddenError(Messages.CANNOT_MODIFY_ADMIN);
    return this.repo.updateUserById(userId, { status: Status.ACTIVE });
  }

  async approveProvider(appId: string) {
    const account = await this.repo.findProviderAccountById(appId);
    if (!account) throw new NotFoundError(Messages.APPLICATION_NOT_FOUND);
    await this.repo.updateProviderAccountStatus(appId, ApplicationStatus.APPROVED);
    return account;
  }

  async rejectProvider(appId: string, reasonCode?: string, adminRemarks?: string) {
    const account = await this.repo.findProviderAccountById(appId);
    if (!account) throw new NotFoundError(Messages.APPLICATION_NOT_FOUND);
    if (!reasonCode || !Object.values(RejectionReasonCode).includes(reasonCode as RejectionReasonCode)) {
      throw new BadRequestError(Messages.REJECTION_REASON_REQUIRED);
    }
    if (reasonCode === RejectionReasonCode.OTHER && (!adminRemarks || !adminRemarks.trim())) {
      throw new BadRequestError("Please provide admin remarks when selecting 'Other' as rejection reason");
    }
    const rejectionReason = REJECTION_REASON_LABELS[reasonCode as RejectionReasonCode];
    await this.repo.updateProviderAccountStatus(appId, ApplicationStatus.REJECTED, reasonCode, rejectionReason, adminRemarks?.trim());
    return account;
  }

  async viewProviders(search?: string, statusFilter?: string) {
    const query: Record<string, unknown> = {};
    if (search) query.name = { $regex: search, $options: "i" };
    if (statusFilter === Status.BLOCKED) {
      query.applicationStatus = ApplicationStatus.SUSPENDED;
    } else {
      query.applicationStatus = { $in: [ApplicationStatus.APPROVED, ApplicationStatus.SUSPENDED] };
    }
    return this.repo.findProviderAccounts(query);
  }

  async blockProvider(providerId: string) {
    const account = await this.repo.findProviderAccountById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_NOT_FOUND);
    await this.repo.updateProviderAccountStatus(providerId, ApplicationStatus.SUSPENDED);
    return account;
  }

  async unblockProvider(providerId: string) {
    const account = await this.repo.findProviderAccountById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_NOT_FOUND);
    await this.repo.updateProviderAccountStatus(providerId, ApplicationStatus.APPROVED);
    return account;
  }
}

import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import { IAuthRepository } from "../interfaces/auth/IAuthRepository";
import { IAuthService } from "../interfaces/auth/IAuthService";
import { SignupDto, LoginDto } from "../dto/auth/auth.dto";
import { StatusCodes } from "../shared/constants/statusCodes";
import { Messages } from "../shared/constants/messages";
import { AppError } from "../shared/errors/AppError";
import { NotFoundError, BadRequestError, UnauthorizedError, ForbiddenError } from "../shared/errors/HttpErrors";

import {
    OTP_EXPIRY_MS,
    BCRYPT_SALT_ROUNDS,
    ACCESS_TOKEN_EXPIRY,
    REFRESH_TOKEN_EXPIRY,
    REFRESH_TOKEN_EXPIRY_MS,
} from "../shared/constants/config";

import { env } from "../config/env";
import { generateOtp } from "../shared/utils/generateOtp";
import { sendEmail } from "../shared/utils/sendEmail";
import { logger } from "../shared/logger/logger";
import { Role } from "../shared/enums/role.enum";
import { AuthUserPayload } from "../shared/interfaces/AuthRequest";

export class AuthService implements IAuthService {
    constructor(private repo: IAuthRepository) { }

    async signup(dto: SignupDto) {
        const existing = await this.repo.findByEmail(dto.email);

        if (existing) {
            throw new BadRequestError(Messages.USER_ALREADY_EXISTS);
        }

        const hashedPassword = await bcrypt.hash(dto.password, BCRYPT_SALT_ROUNDS);

        await this.repo.create({
            ...dto,
            password: hashedPassword,
            isVerified: false,
        });

        const otp = generateOtp();
        const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);

        await this.repo.createOTP(dto.email, otp, expiresAt);
        await sendEmail(dto.email, otp);

        if (dto.phone) {
            const phoneOtp = generateOtp();
            await this.repo.createPhoneOTP(dto.phone, phoneOtp, expiresAt);
            logger.info(`Sending SMS to ${dto.phone}: Your OTP is ${phoneOtp}`);
        }

        logger.info("User signup", { email: dto.email });

        return { message: Messages.OTP_SENT };
    }

    async verifyOtp(email: string, otp: string, phone?: string, phoneOtp?: string) {
        const record = await this.repo.findOTP(email, otp);

        if (!record || record.expiresAt < new Date()) {
            throw new BadRequestError(Messages.EMAIL_OTP_INVALID_OR_EXPIRED);
        }

        if (phone && phoneOtp) {
            const phoneRecord = await this.repo.findPhoneOTP(phone, phoneOtp);
            if (!phoneRecord || phoneRecord.expiresAt < new Date()) {
                throw new BadRequestError(Messages.PHONE_OTP_INVALID_OR_EXPIRED);
            }
            await this.repo.deletePhoneOTP(phone);
        }

        await this.repo.deleteOTP(email);

        const user = await this.repo.findByEmail(email);
        if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);

        await this.repo.updateUser(user._id.toString(), { isVerified: true });

        return { message: Messages.VERIFIED_SUCCESSFULLY };
    }

    async resendOtp(email?: string, phone?: string) {
        const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);

        if (email) {
            await this.repo.deleteOTP(email);
            const newOtp = generateOtp();
            await this.repo.createOTP(email, newOtp, expiresAt);
            await sendEmail(email, newOtp);
        }

        if (phone) {
            await this.repo.deletePhoneOTP(phone);
            const newPhoneOtp = generateOtp();
            await this.repo.createPhoneOTP(phone, newPhoneOtp, expiresAt);
            logger.info(`Resending SMS to ${phone}: Your OTP is ${newPhoneOtp}`);
        }

        return { message: Messages.OTP_RESENT };
    }

    async login(dto: LoginDto, isOAuth: boolean = false, expectedRole: Role = Role.USER) {
        const user = await this.repo.findByEmail(dto.email);
        if (!user) {
            throw new UnauthorizedError(Messages.INVALID_CREDENTIALS);
        }

        if (user.role !== expectedRole) {
            throw new UnauthorizedError(Messages.CROSS_PLATFORM_LOGIN_BLOCKED);
        }

        if (user.status === "blocked") {
            throw new ForbiddenError(Messages.ACCOUNT_BLOCKED);
        }

        if (!user.isVerified) {
            throw new UnauthorizedError(Messages.EMAIL_NOT_VERIFIED);
        }

        if (!isOAuth) {
            const isMatch = await bcrypt.compare(dto.password, user.password);
            if (!isMatch) {
                throw new UnauthorizedError(Messages.INVALID_CREDENTIALS);
            }
        }

        const accessToken = jwt.sign(
            { id: user._id, role: user.role },
            env.JWT_SECRET,
            { expiresIn: ACCESS_TOKEN_EXPIRY }
        );

        const refreshToken = jwt.sign(
            { id: user._id },
            env.REFRESH_SECRET,
            { expiresIn: REFRESH_TOKEN_EXPIRY }
        );

        await this.repo.createRefreshToken(
            user._id.toString(),
            refreshToken,
            new Date(Date.now() + REFRESH_TOKEN_EXPIRY_MS)
        );

        logger.info("User login", { email: dto.email });

        const userSafe = {
    _id: user._id.toString(),
    name: user.name,
    email: user.email,
    phone: user.phone,
    profileImage: user.profileImage,
    role: user.role,
    isVerified: user.isVerified,
};

  return { user: userSafe, accessToken, refreshToken };

    }

    async forgotPassword(email: string) {
        const user = await this.repo.findByEmail(email);
        if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);

        const otp = generateOtp();
        const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);

        await this.repo.createOTP(email, otp, expiresAt);
        await sendEmail(email, otp);

        return { message: Messages.OTP_SENT };
    }

    async resetPassword(email: string, otp: string, newPassword: string) {
        const record = await this.repo.findOTP(email, otp);

        if (!record || record.expiresAt < new Date()) {
            throw new BadRequestError(Messages.OTP_INVALID_OR_EXPIRED);
        }

        const hashedPassword = await bcrypt.hash(newPassword, BCRYPT_SALT_ROUNDS);

        const user = await this.repo.findByEmail(email);
        if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);

        await this.repo.updateUser(user._id.toString(), { password: hashedPassword });
        await this.repo.deleteOTP(email);

        return { message: Messages.PASSWORD_RESET_SUCCESS };
    }

    async refreshToken(token: string) {
        try {
            const tokenDoc = await this.repo.findRefreshToken(token);
            if (!tokenDoc) throw new UnauthorizedError(Messages.INVALID_TOKEN);

            const decoded = jwt.verify(token, env.REFRESH_SECRET) as AuthUserPayload;
            const user = await this.repo.findById(decoded.id);
            if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);

            const newAccessToken = jwt.sign(
                { id: decoded.id, role: user.role },
                env.JWT_SECRET,
                { expiresIn: ACCESS_TOKEN_EXPIRY }
            );

            return { accessToken: newAccessToken };
        } catch (err) {
            if (err instanceof AppError) throw err;
            throw new UnauthorizedError(Messages.INVALID_REFRESH_TOKEN);
        }
    }

    async logout(token: string) {
        await this.repo.deleteRefreshToken(token);
    }
}

import { IBookingRepository } from "../interfaces/booking/IBookingRepository";
import { ISlotRepository } from "../interfaces/slot/ISlotRepository";
import { IBookingService } from "../interfaces/booking/IBookingService";
import { CreateBookingDto, RescheduleBookingDto, BookingQuery, AdminBookingQuery } from "../dto/booking/booking.dto";
import { StatusCodes } from "../shared/constants/statusCodes";
import { ServiceModel } from "../models/service.model";
import { IBooking } from "../models/booking.model";
import { NotFoundError, BadRequestError, ForbiddenError, ConflictError } from "../shared/errors/HttpErrors";

export class BookingService implements IBookingService {
  constructor(
    private readonly repo: IBookingRepository,
    private readonly slotRepo: ISlotRepository
  ) {}

  async createBooking(userId: string, data: CreateBookingDto) {
    const service = await ServiceModel.findById(data.serviceId).lean();
    if (!service) throw new NotFoundError("Service not found");

    const slot = await this.slotRepo.findById(data.slotId);
    if (!slot) throw new NotFoundError("Slot not found");
    if (slot.slotStatus !== "available") throw new ConflictError("Slot is not available");

    const locked = await this.slotRepo.acquireLock(data.slotId, userId);
    if (!locked) throw new ConflictError("Slot is no longer available");

    await this.slotRepo.markBooked(data.slotId, data.serviceId);

    const booking = await this.repo.create({
      userId: userId as unknown as IBooking["userId"],
      providerId: service.providerId,
      serviceId: data.serviceId as unknown as IBooking["serviceId"],
      slotId: data.slotId as unknown as IBooking["slotId"],
      date: slot.date,
      startTime: slot.startTime,
      endTime: slot.endTime,
      address: data.address,
      amount: service.price,
      bookingStatus: "confirmed",
      paymentStatus: "pending",
      statusHistory: [{ status: "confirmed", at: new Date() }],
    });

    return this.repo.findById(String(booking._id));
  }

  async getAllBookings(
    status?: AdminBookingQuery["status"],
    search?: AdminBookingQuery["search"],
    page = 1,
    limit = 20
  ) {
    return this.repo.findAllBookings(status, search, page, limit);
  }

  async getUserBookings(userId: string, query: BookingQuery) {
    return this.repo.findByUser(userId, query.status, query.page, query.limit);
  }

  async getProviderBookings(providerId: string, query: BookingQuery) {
    return this.repo.findByProvider(providerId, query.status, query.page, query.limit);
  }

  async getBookingById(id: string, userId: string) {
    const booking = await this.repo.findById(id);
    if (!booking) throw new NotFoundError("Booking not found");
    if (String(booking.userId) !== userId && String(booking.providerId) !== userId) {
      throw new ForbiddenError("Unauthorized");
    }
    return booking;
  }

  async reschedule(bookingId: string, userId: string, data: RescheduleBookingDto) {
    const booking = await this.repo.findById(bookingId);
    if (!booking) throw new NotFoundError("Booking not found");
    if (String(booking.userId) !== userId) throw new ForbiddenError("Unauthorized");
    if (["cancelled", "completed", "rejected"].includes(booking.bookingStatus)) {
      throw new BadRequestError("Cannot reschedule this booking");
    }

    const bookingTime = new Date(`${booking.date}T${booking.startTime}:00`);
    if (bookingTime.getTime() - Date.now() < 24 * 60 * 60 * 1000) {
      throw new BadRequestError("Reschedule must be at least 24 hours before booking time");
    }

    const newSlot = await this.slotRepo.findById(data.newSlotId);
    if (!newSlot) throw new NotFoundError("New slot not found");
    if (newSlot.slotStatus !== "available") throw new ConflictError("New slot is not available");

    // Release old slot
    await this.slotRepo.updateSlot(String(booking.slotId), String(booking.providerId), { slotStatus: "available" });

    // Book new slot
    const locked = await this.slotRepo.acquireLock(data.newSlotId, userId);
    if (!locked) throw new ConflictError("New slot is no longer available");
    await this.slotRepo.markBooked(data.newSlotId, String(booking.serviceId));

    const history = [
      ...(booking.statusHistory || []),
      {
        status: "confirmed" as const,
        at: new Date(),
        note: `Rescheduled from ${booking.date} ${booking.startTime} to ${newSlot.date} ${newSlot.startTime}`,
      },
    ];

    return this.repo.updateBooking(bookingId, {
      slotId: data.newSlotId as unknown as IBooking["slotId"],
      date: newSlot.date,
      startTime: newSlot.startTime,
      endTime: newSlot.endTime,
      statusHistory: history,
    });
  }

  async updateStatus(bookingId: string, providerId: string, status: "in_progress" | "completed") {
    const booking = await this.repo.findById(bookingId);
    if (!booking) throw new NotFoundError("Booking not found");
    if (String(booking.providerId) !== providerId) {
      throw new ForbiddenError("Unauthorized");
    }
    if (status === "in_progress" && booking.bookingStatus !== "confirmed") {
      throw new BadRequestError("Can only start confirmed bookings");
    }
    if (status === "completed" && booking.bookingStatus !== "in_progress") {
      throw new BadRequestError("Can only complete in-progress bookings");
    }
    const history = [...(booking.statusHistory || []), { status, at: new Date() }];
    return this.repo.updateBooking(bookingId, { bookingStatus: status, statusHistory: history });
  }

  async cancel(bookingId: string, userId: string, reason?: string) {
    const booking = await this.repo.findById(bookingId);
    if (!booking) throw new NotFoundError("Booking not found");
    if (String(booking.userId) !== userId && String(booking.providerId) !== userId) {
      throw new ForbiddenError("Unauthorized");
    }
    if (["cancelled", "completed"].includes(booking.bookingStatus)) {
      throw new BadRequestError("Cannot cancel this booking");
    }

    await this.slotRepo.updateSlot(String(booking.slotId), String(booking.providerId), { slotStatus: "available" });

    const cancelledBy: "user" | "provider" = String(booking.userId) === userId ? "user" : "provider";
    const history = [
      ...(booking.statusHistory || []),
      { status: "cancelled" as const, at: new Date(), note: reason },
    ];

    return this.repo.updateBooking(bookingId, {
      bookingStatus: "cancelled",
      cancelledBy,
      cancelReason: reason,
      statusHistory: history,
    });
  }
}

import { IConversationRepository, IMessageRepository } from "../interfaces/messaging/IMessagingRepository";
import { IMessagingService } from "../interfaces/messaging/IMessagingService";
import { IConversation, IMessage } from "../models/messaging.model";
import { SenderRole } from "../dto/messaging/messaging.dto";
import { StatusCodes } from "../shared/constants/statusCodes";
import { NotFoundError, ForbiddenError } from "../shared/errors/HttpErrors";

export interface PaginatedConversationResponse {
  items: IConversation[];
  total: number;
  page: number;
  limit: number;
}

export class MessagingService implements IMessagingService {
  constructor(
    private readonly conversationRepo: IConversationRepository,
    private readonly messageRepo: IMessageRepository
  ) {}

  async getOrCreateConversation(
    userId: string,
    providerId: string,
    serviceId?: string,
    bookingId?: string
  ): Promise<IConversation> {
    const existing = await this.conversationRepo.findByParticipants(userId, providerId);
    if (existing) return existing;
    return this.conversationRepo.create({ userId, providerId, serviceId, bookingId } as unknown as Partial<IConversation>);
  }

  async getUserConversations(userId: string): Promise<IConversation[]> {
    return this.conversationRepo.findByUser(userId);
  }

  async getUserConversationsWithPagination(
    userId: string,
    search?: string,
    page = 1,
    limit = 20
  ): Promise<PaginatedConversationResponse> {
    const result = await (this.conversationRepo as any).findByUserWithPagination(userId, search, page, limit);
    return {
      items: result.items,
      total: result.total,
      page,
      limit,
    };
  }

  async getProviderConversations(providerId: string): Promise<IConversation[]> {
    return this.conversationRepo.findByProvider(providerId);
  }

  async getProviderConversationsWithPagination(
    providerId: string,
    search?: string,
    page = 1,
    limit = 20
  ): Promise<PaginatedConversationResponse> {
    const result = await (this.conversationRepo as any).findByProviderWithPagination(providerId, search, page, limit);
    return {
      items: result.items,
      total: result.total,
      page,
      limit,
    };
  }

  async getMessages(
    conversationId: string,
    requesterId: string,
    page = 1,
    limit = 50
  ): Promise<IMessage[]> {
    const conv = await this.conversationRepo.findById(conversationId);
    if (!conv) throw new NotFoundError("Conversation not found");
    if (String(conv.userId) !== requesterId && String(conv.providerId) !== requesterId) {
      throw new ForbiddenError("Unauthorized");
    }
    return this.messageRepo.findByConversation(conversationId, page, limit);
  }

  async sendMessage(
    conversationId: string,
    senderId: string,
    senderRole: SenderRole,
    content: string
  ): Promise<IMessage> {
    const conv = await this.conversationRepo.findById(conversationId);
    if (!conv) throw new NotFoundError("Conversation not found");
    if (String(conv.userId) !== senderId && String(conv.providerId) !== senderId) {
      throw new ForbiddenError("Unauthorized");
    }
    const message = await this.messageRepo.create({ conversationId, senderId, senderRole, content } as unknown as Partial<IMessage>);
    await this.conversationRepo.updateLastMessage(conversationId, content, senderRole);
    return message;
  }

  async markRead(conversationId: string, userId: string, role: SenderRole): Promise<void> {
    const conv = await this.conversationRepo.findById(conversationId);
    if (!conv) return;
    await this.messageRepo.markReadByRecipient(conversationId, userId);
    await this.conversationRepo.resetUnreadCount(conversationId, role);
  }

  async getUnreadCount(userId: string, role: SenderRole): Promise<number> {
    return role === "user"
      ? this.conversationRepo.sumUnreadByUser(userId)
      : this.conversationRepo.sumUnreadByProvider(userId);
  }
}

import { Types } from "mongoose";
import bcrypt from "bcryptjs";
import { IProviderRepository } from "../interfaces/provider/IProviderRepository";
import { IProviderService } from "../interfaces/provider/IProviderService";
import { IServiceRepository } from "../interfaces/service/IServiceRepository";
import { 
  ProviderApplicationDto, 
  UpdateProviderProfileDto, 
  ProviderQuery,
} from "../dto/provider/provider.dto";
import { IProviderAccount } from "../models/providerAccount.model";
import { ApplicationStatus } from "../shared/enums/application-status.enum";
import { escapeRegex } from "../shared/utils/search";
import { Messages } from "../shared/constants/messages";
import { StatusCodes } from "../shared/constants/statusCodes";
import { geocodeAddress, reverseGeocode } from "../shared/utils/geocoding";
import { mapProviderListItem, mapProviderDetails, mapApplication, mapProviderProfile } from "../mappers/provider.mapper";
import { NotFoundError, BadRequestError } from "../shared/errors/HttpErrors";


// ── Location resolver ─────────────────────────────────────────────────────────

async function resolveLocation(data: ProviderApplicationDto | UpdateProviderProfileDto) {
  const fields: Record<string, unknown> = {};
  if (data.latitude && data.longitude) {
    fields.location = { type: "Point", coordinates: [data.longitude, data.latitude] };
    if (!data.state || !data.city) {
      const geo = await reverseGeocode(data.latitude, data.longitude);
      if (geo) {
        fields.state = data.state || geo.state;
        fields.district = data.district || geo.district;
        fields.city = data.city || geo.city;
        fields.pincode = data.pincode || geo.pincode;
        fields.fullAddress = data.fullAddress || geo.fullAddress;
      }
    }
    if (data.state) fields.state = data.state;
    if (data.district) fields.district = data.district;
    if (data.city) fields.city = data.city;
    if (data.pincode) fields.pincode = data.pincode;
    if (data.fullAddress) fields.fullAddress = data.fullAddress;
  } else if (data.pincode || data.city || data.fullAddress) {
    const query = data.fullAddress || data.pincode || data.city || "";
    const geo = await geocodeAddress(query);
    if (geo) {
      fields.location = { type: "Point", coordinates: [geo.longitude, geo.latitude] };
      fields.state = data.state || geo.state;
      fields.district = data.district || geo.district;
      fields.city = data.city || geo.city;
      fields.pincode = data.pincode || geo.pincode;
      fields.fullAddress = data.fullAddress || geo.fullAddress;
    }
  }
  if (data.serviceRadius) fields.serviceRadius = data.serviceRadius;
  return fields;
}

// ── Service ───────────────────────────────────────────────────────────────────

export class ProviderService implements IProviderService {
  constructor(
    private readonly repo: IProviderRepository,
    private readonly serviceRepo: IServiceRepository
  ) {}

  async applyProvider(providerId: string, data: ProviderApplicationDto) {
    const account = await this.repo.findById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    if (account.applicationStatus !== ApplicationStatus.NOT_APPLIED) {
      throw new BadRequestError(Messages.APPLICATION_ALREADY_SUBMITTED);
    }
    const locationFields = await resolveLocation(data);
    const updated = await this.repo.updateAccount(providerId, {
      categoryId: new Types.ObjectId(data.categoryId),
      subCategory: data.subCategory,
      experience: data.experience,
      address: data.address,
      description: data.description,
      serviceArea: data.serviceArea,
      documentType: data.documentType,
      headshot: data.headshot,
      documents: data.documents ?? [],
      businessName: data.businessName,
      applicationStatus: ApplicationStatus.PENDING,
      ...locationFields,
    } as Partial<IProviderAccount>);
    return mapApplication(updated!);
  }

  async getApplicationStatus(providerId: string) {
    const account = await this.repo.findById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    if (account.applicationStatus === ApplicationStatus.NOT_APPLIED) {
      return { status: ApplicationStatus.NOT_APPLIED, rejectionReason: null };
    }
    return {
      id: account._id,
      status: account.applicationStatus,
      rejectionReasonCode: account.rejectionReasonCode ?? null,
      rejectionReason: account.rejectionReason ?? null,
      adminRemarks: account.adminRemarks ?? null,
      rejectedAt: account.rejectedAt ?? null,
      category: account.categoryId,
      fullName: account.name,
      email: account.email,
      phone: account.phone,
      experience: account.experience,
      description: account.description,
      address: account.address,
      serviceArea: account.serviceArea,
      documentType: account.documentType,
      subCategory: account.subCategory,
      headshot: account.headshot,
      documents: account.documents,
    };
  }

  async reapplyProvider(providerId: string, data: ProviderApplicationDto) {
    const account = await this.repo.findById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    if (account.applicationStatus !== ApplicationStatus.REJECTED) {
      throw new BadRequestError(Messages.NO_REJECTED_APPLICATION);
    }
    const locationFields = await resolveLocation(data);
    const updated = await this.repo.updateAccount(providerId, {
      categoryId: new Types.ObjectId(data.categoryId),
      subCategory: data.subCategory,
      experience: data.experience,
      address: data.address,
      description: data.description,
      serviceArea: data.serviceArea,
      documentType: data.documentType,
      headshot: data.headshot,
      documents: data.documents ?? [],
      businessName: data.businessName,
      applicationStatus: ApplicationStatus.PENDING,
      rejectionReasonCode: undefined,
      rejectionReason: undefined,
      adminRemarks: undefined,
      rejectedAt: undefined,
      ...locationFields,
    } as Partial<IProviderAccount>);
    return mapApplication(updated!);
  }

  async getPublicProviders(query: ProviderQuery = {}, limit?: number) {
    if (query.latitude && query.longitude) {
      const radius = query.radius || 10;
      const providers = await this.repo.findNearbyProviders(query.longitude, query.latitude, radius * 1000, query.categoryId, query.search, limit);
      if (providers.length > 0) return providers.map(mapProviderListItem);
      if (query.search) {
        const filter: Record<string, unknown> = {};
        if (query.categoryId && Types.ObjectId.isValid(query.categoryId)) filter.categoryId = query.categoryId;
        const searchRegex = { $regex: escapeRegex(query.search), $options: "i" };
        filter.$or = [
          { name: searchRegex }, { businessName: searchRegex }, { "services.name": searchRegex },
          { city: searchRegex }, { district: searchRegex }, { state: searchRegex },
          { pincode: searchRegex }, { fullAddress: searchRegex }, { serviceArea: searchRegex }, { serviceAreas: searchRegex },
        ];
        const fallback = await this.repo.findApprovedProviders(filter, limit);
        return fallback.map(mapProviderListItem);
      }
      return [];
    }
    const filter: Record<string, unknown> = {};
    if (query.categoryId) {
      if (!Types.ObjectId.isValid(query.categoryId)) return [];
      filter.categoryId = query.categoryId;
    }
    if (query.search) {
      const searchRegex = { $regex: escapeRegex(query.search), $options: "i" };
      filter.$or = [
        { name: searchRegex }, { businessName: searchRegex }, { "services.name": searchRegex },
        { city: searchRegex }, { district: searchRegex }, { state: searchRegex },
        { pincode: searchRegex }, { fullAddress: searchRegex }, { serviceArea: searchRegex }, { serviceAreas: searchRegex },
      ];
    }
    const providers = await this.repo.findApprovedProviders(filter, limit);
    return providers.map(mapProviderListItem);
  }

  async getPublicProviderById(id: string) {
    const provider = await this.repo.findApprovedProviderById(id);
    if (!provider) throw new NotFoundError(Messages.PROVIDER_NOT_FOUND);
    const subcategoriesWorkedIn = await this.serviceRepo.findProviderSubcategories(String(provider._id));
    return { ...mapProviderDetails(provider), subcategoriesWorkedIn };
  }

  async getProfile(providerId: string) {
    const account = await this.repo.findById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_PROFILE_NOT_FOUND);
    return mapProviderProfile(account);

  }

  async updateProfile(providerId: string, data: UpdateProviderProfileDto) {
    const locationFields = await resolveLocation(data);
    const updated = await this.repo.updateAccount(providerId, {
      ...(data.categoryId && { categoryId: new Types.ObjectId(data.categoryId) }),
      ...(data.experience && { experience: data.experience }),
      ...(data.description && { description: data.description }),
      ...(data.serviceArea && { serviceAreas: [data.serviceArea] }),
      ...(data.headshot && { headshot: data.headshot }),
      ...locationFields,
    } as Partial<IProviderAccount>);
    if (!updated) throw new NotFoundError(Messages.PROVIDER_PROFILE_NOT_FOUND);
    return mapProviderProfile(updated);
  }

  async getDashboard(providerId: string) {
    const account = await this.repo.findById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_PROFILE_NOT_FOUND);
    const [totalServices, activeServices] = await Promise.all([
      this.serviceRepo.countByProvider(providerId),
      this.serviceRepo.countByProvider(providerId, "active"),
    ]);
    return { totalServices, activeServices, profileCompletion: this.getProfileCompletion(account) };
  }

  async requestApplicationStatusOtp(_email: string): Promise<{ message: string }> {
    throw new BadRequestError("OTP-based status checking has been removed.");
  }

  async verifyApplicationStatusOtp(_email: string, _otp: string): Promise<null> {
    throw new BadRequestError("OTP-based status checking has been removed.");
  }

  async changePassword(providerId: string, oldPassword: string, newPassword: string) {
    const account = await this.repo.findById(providerId);
    if (!account) throw new NotFoundError(Messages.PROVIDER_PROFILE_NOT_FOUND);
    const isMatch = await bcrypt.compare(oldPassword, account.password);
    if (!isMatch) throw new BadRequestError("Current password is incorrect");
    const hash = await bcrypt.hash(newPassword, 10);
    await this.repo.updateAccount(providerId, { password: hash } as Partial<IProviderAccount>);
    return { message: "Password updated successfully" };
  }


  private getProfileCompletion(account: IProviderAccount): number {
    const checks = [
      account.name,
      account.experience !== undefined && account.experience !== null,
      account.description,
      account.categoryId,
      account.serviceAreas?.length,
    ];
    return Math.round((checks.filter(Boolean).length / checks.length) * 100);
  }
}

import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import { IProviderRepository } from "../interfaces/provider/IProviderRepository";
import { StatusCodes } from "../shared/constants/statusCodes";
import { Messages } from "../shared/constants/messages";
import {
  OTP_EXPIRY_MS,
  BCRYPT_SALT_ROUNDS,
  ACCESS_TOKEN_EXPIRY,
  REFRESH_TOKEN_EXPIRY,
  REFRESH_TOKEN_EXPIRY_MS,
} from "../shared/constants/config";
import { env } from "../config/env";
import { generateOtp } from "../shared/utils/generateOtp";
import { sendEmail } from "../shared/utils/sendEmail";
import { logger } from "../shared/logger/logger";
import { Role } from "../shared/enums/role.enum";
import { AppError } from "../shared/errors/AppError";
import { NotFoundError, BadRequestError, UnauthorizedError } from "../shared/errors/HttpErrors";
import { ApplicationStatus } from "../shared/enums/application-status.enum";
import { AuthUserPayload } from "../shared/interfaces/AuthRequest";
import { OTPModel } from "../models/otp.model";
import { TokenModel } from "../models/token.model";
import { ProviderAccountModel, IProviderAccount } from "../models/providerAccount.model";
import { ProviderSignupDto, ProviderLoginDto } from "../dto/provider/providerAuth.dto";
export class ProviderAuthService {
  constructor(private readonly repo: IProviderRepository) {}

  async signup(dto: ProviderSignupDto) {
    const existing = await ProviderAccountModel.findOne({ email: dto.email });
    if (existing) throw new BadRequestError(Messages.PROVIDER_ACCOUNT_EXISTS);

    const hashedPassword = await bcrypt.hash(dto.password, BCRYPT_SALT_ROUNDS);
    await ProviderAccountModel.create({
      name: dto.name,
      email: dto.email,
      phone: dto.phone,
      password: hashedPassword,
      isVerified: false,
      applicationStatus: ApplicationStatus.NOT_APPLIED,
    });

    const otp = generateOtp();
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);
    await OTPModel.create({ email: dto.email, otp, expiresAt });
    await sendEmail(dto.email, otp);
    logger.info("Provider signup", { email: dto.email });
    return { message: Messages.PROVIDER_SIGNUP_SUCCESS };
  }

  async verifyOtp(email: string, otp: string) {
    const record = await OTPModel.findOne({ email, otp });
    if (!record || record.expiresAt < new Date()) {
      throw new BadRequestError(Messages.OTP_INVALID_OR_EXPIRED);
    }
    await OTPModel.deleteMany({ email });
    const account = await ProviderAccountModel.findOne({ email });
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    await ProviderAccountModel.findByIdAndUpdate(account._id, { isVerified: true });
    return { message: Messages.VERIFIED_SUCCESSFULLY };
  }

  async resendOtp(email: string) {
    const account = await ProviderAccountModel.findOne({ email });
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    await OTPModel.deleteMany({ email });
    const otp = generateOtp();
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);
    await OTPModel.create({ email, otp, expiresAt });
    await sendEmail(email, otp);
    return { message: Messages.OTP_RESENT };
  }

  async login(dto: ProviderLoginDto) {
    const account = await ProviderAccountModel.findOne({ email: dto.email });
    if (!account) throw new UnauthorizedError(Messages.INVALID_CREDENTIALS);
    if (!account.isVerified) throw new UnauthorizedError(Messages.EMAIL_NOT_VERIFIED);
    const isMatch = await bcrypt.compare(dto.password, account.password);
    if (!isMatch) throw new UnauthorizedError(Messages.INVALID_CREDENTIALS);

    const accessToken = jwt.sign(
      { id: account._id, role: Role.PROVIDER, applicationStatus: account.applicationStatus },
      env.JWT_SECRET,
      { expiresIn: ACCESS_TOKEN_EXPIRY }
    );
    const refreshToken = jwt.sign({ id: account._id }, env.REFRESH_SECRET, { expiresIn: REFRESH_TOKEN_EXPIRY });
    await TokenModel.create({
      userId: account._id,
      token: refreshToken,
      expiresAt: new Date(Date.now() + REFRESH_TOKEN_EXPIRY_MS),
    });

    logger.info("Provider login", { email: dto.email });
    return {
      user: {
        _id: account._id,
        name: account.name,
        email: account.email,
        phone: account.phone,
        role: Role.PROVIDER,
        applicationStatus: account.applicationStatus,
      },
      accessToken,
      refreshToken,
    };
  }

  async forgotPassword(email: string) {
    const account = await ProviderAccountModel.findOne({ email });
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    const otp = generateOtp();
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);
    await OTPModel.create({ email, otp, expiresAt });
    await sendEmail(email, otp);
    return { message: Messages.OTP_SENT };
  }

  async resetPassword(email: string, otp: string, newPassword: string) {
    const record = await OTPModel.findOne({ email, otp });
    if (!record || record.expiresAt < new Date()) {
      throw new BadRequestError(Messages.OTP_INVALID_OR_EXPIRED);
    }
    const account = await ProviderAccountModel.findOne({ email });
    if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
    await ProviderAccountModel.findByIdAndUpdate(account._id, {
      password: await bcrypt.hash(newPassword, BCRYPT_SALT_ROUNDS),
    });
    await OTPModel.deleteMany({ email });
    return { message: Messages.PASSWORD_RESET_SUCCESS };
  }

  async refreshToken(token: string) {
    try {
      const tokenDoc = await TokenModel.findOne({ token });
      if (!tokenDoc) throw new UnauthorizedError(Messages.INVALID_TOKEN);
      const decoded = jwt.verify(token, env.REFRESH_SECRET) as AuthUserPayload;
      const account = await this.repo.findById(decoded.id);
      if (!account) throw new NotFoundError(Messages.PROVIDER_ACCOUNT_NOT_FOUND);
      const newAccessToken = jwt.sign(
        { id: decoded.id, role: Role.PROVIDER, applicationStatus: account.applicationStatus },
        env.JWT_SECRET,
        { expiresIn: ACCESS_TOKEN_EXPIRY }
      );
      return { accessToken: newAccessToken };
    } catch (err) {
      if (err instanceof AppError) throw err;
      throw new UnauthorizedError(Messages.INVALID_REFRESH_TOKEN);
    }
  }

  async logout(token: string) {
    await TokenModel.deleteOne({ token });
  }
}

import { IProviderQuoteRepository } from "../interfaces/provider-quote/IProviderQuoteRepository";
import { IServiceRequestRepository } from "../interfaces/service-request/IServiceRequestRepository";
import { IProviderQuoteService, ProviderQuoteListResult, ProviderQuoteStats, AcceptQuoteResult } from "../interfaces/provider-quote/IProviderQuoteService";
import { CreateProviderQuoteDto, UpdateProviderQuoteDto } from "../dto/provider-quote/providerQuote.dto";
import { IProviderQuote } from "../models/providerQuote.model";
import { BookingModel } from "../models/booking.model";
import { StatusCodes } from "../shared/constants/statusCodes";
import { NotFoundError, BadRequestError, ForbiddenError, ConflictError } from "../shared/errors/HttpErrors";

export class ProviderQuoteService implements IProviderQuoteService {
  constructor(
    private readonly repo: IProviderQuoteRepository,
    private readonly requestRepo: IServiceRequestRepository
  ) {}

  async submitQuote(providerId: string, dto: CreateProviderQuoteDto): Promise<IProviderQuote | null> {
    const request = await this.requestRepo.findById(dto.serviceRequestId);
    if (!request) throw new NotFoundError("Service request not found");
    if (!["open", "receiving_quotes"].includes(request.status)) {
      throw new BadRequestError("This request is no longer accepting quotes");
    }
    const existing = await this.repo.findExisting(dto.serviceRequestId, providerId);
    if (existing) throw new ConflictError("You have already submitted a quote");

    const quote = await this.repo.create({
      ...dto,
      providerId: providerId as unknown as IProviderQuote["providerId"],
      serviceRequestId: dto.serviceRequestId as unknown as IProviderQuote["serviceRequestId"],
    });

    await this.requestRepo.incrementQuoteCount(dto.serviceRequestId);
    if (request.status === "open") {
      await this.requestRepo.updateStatus(dto.serviceRequestId, "receiving_quotes");
    }
    return this.repo.findById(String(quote._id));
  }

  async updateQuote(quoteId: string, providerId: string, dto: UpdateProviderQuoteDto): Promise<IProviderQuote | null> {
    const existing = await this.repo.findById(quoteId);
    if (!existing) throw new NotFoundError("Quote not found");
    if (existing.status !== "pending") throw new BadRequestError("Cannot edit a non-pending quote");
    return this.repo.updateQuote(quoteId, providerId, dto as Partial<IProviderQuote>);
  }

  async withdrawQuote(quoteId: string, providerId: string): Promise<{ message: string }> {
    const quote = await this.repo.findById(quoteId);
    if (!quote) throw new NotFoundError("Quote not found");
    const pid = (quote.providerId as unknown as { _id?: unknown })._id || quote.providerId;
    if (String(pid) !== providerId) throw new ForbiddenError("Unauthorized");
    if (quote.status !== "pending") throw new BadRequestError("Cannot withdraw this quote");
    await this.repo.updateStatus(quoteId, "withdrawn");
    await this.requestRepo.decrementQuoteCount(String(quote.serviceRequestId));
    return { message: "Quote withdrawn" };
  }

  async getQuotesForRequest(serviceRequestId: string): Promise<IProviderQuote[]> {
    return this.repo.findByRequestId(serviceRequestId);
  }

  async getProviderQuotes(providerId: string, page?: number, limit?: number): Promise<ProviderQuoteListResult> {
    return this.repo.findByProvider(providerId, page, limit);
  }

  async acceptQuote(quoteId: string, userId: string): Promise<AcceptQuoteResult> {
    const quote = await this.repo.findById(quoteId);
    if (!quote) throw new NotFoundError("Quote not found");

    const request = await this.requestRepo.findById(String(quote.serviceRequestId));
    if (!request) throw new NotFoundError("Service request not found");
    const uid = (request.userId as unknown as { _id?: unknown })._id || request.userId;
    if (String(uid) !== userId) throw new ForbiddenError("Unauthorized");
    if (quote.status !== "pending") throw new BadRequestError("Quote is no longer pending");

    await this.repo.updateStatus(quoteId, "accepted");
    await this.repo.rejectAllExcept(String(quote.serviceRequestId), quoteId);

    const booking = await BookingModel.create({
      userId: request.userId,
      providerId: quote.providerId,
      serviceId: request.categoryId,
      slotId: request._id,
      date: request.preferredDate || new Date().toISOString().split("T")[0],
      startTime: request.preferredTime || "09:00",
      endTime: "18:00",
      address: request.address,
      amount: quote.price,
      bookingStatus: "confirmed",
      paymentStatus: "pending",
      statusHistory: [{ status: "confirmed", at: new Date(), note: "Created from accepted quote" }],
    });

    await this.requestRepo.updateStatus(String(request._id), "booking_created", {
      selectedQuoteId: quote._id,
      selectedProviderId: quote.providerId as unknown as IProviderQuote["providerId"],
      bookingId: booking._id,
    } as never);

    return { quote, booking };
  }

  async getProviderStats(providerId: string): Promise<ProviderQuoteStats> {
    const [total, accepted, pending] = await Promise.all([
      this.repo.countByProvider(providerId),
      this.repo.countByProvider(providerId, "accepted"),
      this.repo.countByProvider(providerId, "pending"),
    ]);
    return { total, accepted, pending, acceptanceRate: total > 0 ? Math.round((accepted / total) * 100) : 0 };
  }
}

import { IServiceRepository } from "../interfaces/service/IServiceRepository";
import { IServiceService, ServiceListResult } from "../interfaces/service/IServiceService";
import {
  ServiceDto,
  UpdateServiceDto,
  ProviderServiceQuery,
  AdminServiceQuery,
  PublicServiceQuery,
} from "../dto/service/service.dto";
import { IService } from "../models/service.model";
import { Messages } from "../shared/constants/messages";
import { StatusCodes } from "../shared/constants/statusCodes";
import { mapService } from "../mappers/service.mapper";
import { NotFoundError, BadRequestError, ForbiddenError } from "../shared/errors/HttpErrors";


export class ServiceService implements IServiceService {
  constructor(private readonly repo: IServiceRepository) {}

  async createService(providerId: string, data: ServiceDto, providerCategoryId: string | null | undefined) {
    if (!providerCategoryId) {
      throw new BadRequestError("Your account is missing an approved category.");
    }
    const created = await this.repo.createService(providerId, { ...data, categoryId: providerCategoryId });
    const populated = await this.repo.findByIdForProvider(String(created._id), providerId);
    return mapService(populated!);
  }

  async getServices(providerId: string, query?: ProviderServiceQuery) {
    const services = await this.repo.findByProvider(providerId, query);
    return services.map(mapService);
  }

  async getServiceById(providerId: string, id: string) {
    const service = await this.repo.findByIdForProvider(id, providerId);
    if (!service) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    return mapService(service);
  }

  async updateService(providerId: string, id: string, data: UpdateServiceDto) {
    const existing = await this.repo.findByIdForProvider(id, providerId);
    if (!existing) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    if (existing.isBlocked) throw new ForbiddenError(Messages.SERVICE_BLOCKED_BY_ADMIN);
    const updated = await this.repo.updateService(id, providerId, data);
    if (!updated) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    return mapService(updated);
  }

  async deleteService(providerId: string, id: string): Promise<void> {
    const deleted = await this.repo.softDelete(id, providerId);
    if (!deleted) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
  }

  async activateService(providerId: string, id: string) {
    return this.setProviderStatus(providerId, id, "active");
  }

  async deactivateService(providerId: string, id: string) {
    return this.setProviderStatus(providerId, id, "inactive");
  }

  private async setProviderStatus(providerId: string, id: string, status: "active" | "inactive") {
    const existing = await this.repo.findByIdForProvider(id, providerId);
    if (!existing) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    if (existing.isBlocked) throw new ForbiddenError(Messages.SERVICE_BLOCKED_BY_ADMIN);
    if (existing.status === status) return mapService(existing);
    const updated = await this.repo.updateService(id, providerId, { status });
    return mapService(updated!);
  }

  async adminListServices(query: AdminServiceQuery): Promise<ServiceListResult> {
    const { items, total } = await this.repo.findAllForAdmin(query);
    return { items: items.map(mapService), total, page: query.page ?? 1, limit: query.limit ?? 20 };
  }

  async adminBlockService(id: string) {
    const existing = await this.repo.findById(id);
    if (!existing) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    return mapService((await this.repo.setBlocked(id, true))!);
  }

  async adminUnblockService(id: string) {
    const existing = await this.repo.findById(id);
    if (!existing) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    return mapService((await this.repo.setBlocked(id, false))!);
  }

  async publicListServices(query: PublicServiceQuery & { nearbyProviderIds?: string[] }): Promise<ServiceListResult> {
    const { items, total } = await this.repo.findPublic(query);
    return { items: items.map(mapService), total, page: query.page ?? 1, limit: query.limit ?? 20 };
  }

  async publicGetServiceById(id: string) {
    const service = await this.repo.findPublicById(id);
    if (!service) throw new NotFoundError(Messages.SERVICE_NOT_FOUND);
    return mapService(service);
  }

  async getProviderSubcategories(providerId: string): Promise<string[]> {
    return this.repo.findProviderSubcategories(providerId);
  }

  async publicListByProvider(providerId: string, subCategory?: string) {
    const items = await this.repo.findPublicByProvider(providerId, subCategory);
    return items.map(mapService);
  }
}

import { IServiceRequestRepository } from "../interfaces/service-request/IServiceRequestRepository";
import { IServiceRequestService, ServiceRequestListResult, UserRequestStats } from "../interfaces/service-request/IServiceRequestService";
import { CreateServiceRequestDto } from "../dto/service-request/serviceRequest.dto";
import { IServiceRequest, ServiceRequestStatus } from "../models/serviceRequest.model";
import { StatusCodes } from "../shared/constants/statusCodes";
import { NotFoundError, BadRequestError, ForbiddenError } from "../shared/errors/HttpErrors";

export class ServiceRequestService implements IServiceRequestService {
  constructor(private readonly repo: IServiceRequestRepository) {}

  async create(userId: string, dto: CreateServiceRequestDto): Promise<IServiceRequest | null> {
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 7);
    const request = await this.repo.create({
      ...dto,
      userId: userId as unknown as IServiceRequest["userId"],
      categoryId: dto.categoryId as unknown as IServiceRequest["categoryId"],
      status: "open",
      quoteCount: 0,
      expiresAt,
    });
    return this.repo.findById(String(request._id));
  }

  async getById(id: string): Promise<IServiceRequest> {
    const request = await this.repo.findById(id);
    if (!request) throw new NotFoundError("Service request not found");
    return request;
  }

  async getUserRequests(
    userId: string,
    status?: ServiceRequestStatus,
    page?: number,
    limit?: number
  ): Promise<ServiceRequestListResult> {
    return this.repo.findByUser(userId, status, page, limit);
  }

  async getForProviders(filter: {
    categoryId?: string;
    subCategory?: string;
    city?: string;
    coordinates?: [number, number];
    radius?: number;
    page?: number;
    limit?: number;
  }): Promise<ServiceRequestListResult> {
    return this.repo.findForProviders(filter);
  }

  async cancel(id: string, userId: string): Promise<IServiceRequest | null> {
    const request = await this.repo.findById(id);
    if (!request) throw new NotFoundError("Service request not found");
    if (String((request.userId as unknown as { _id?: unknown })._id || request.userId) !== userId) {
      throw new ForbiddenError("Unauthorized");
    }
    if (["booking_created", "completed", "cancelled"].includes(request.status)) {
      throw new BadRequestError("Cannot cancel this request");
    }
    return this.repo.updateStatus(id, "cancelled");
  }

  async getUserStats(userId: string): Promise<UserRequestStats> {
    const [total, active, open, completed] = await Promise.all([
      this.repo.countByUser(userId),
      this.repo.countByUser(userId, "receiving_quotes"),
      this.repo.countByUser(userId, "open"),
      this.repo.countByUser(userId, "completed"),
    ]);
    return { total, active: active + open, completed };
  }
}

import { IUserRepository } from "../interfaces/user/IUserRepository";
import { IUserService } from "../interfaces/user/IUserService";
import { UpdateUserDto, AddressDto, ChangePasswordDto } from "../dto/user/user.dto";
import bcrypt from "bcryptjs";
import { logger } from "../shared/logger/logger";
import { generateOtp } from "../shared/utils/generateOtp";
import { Messages } from "../shared/constants/messages";
import { StatusCodes } from "../shared/constants/statusCodes";
import { OTP_EXPIRY_MS, BCRYPT_SALT_ROUNDS } from "../shared/constants/config";
import { IUser } from "../models/user.model";
import { NotFoundError, BadRequestError } from "../shared/errors/HttpErrors";

// Strip password from any user document
const withoutPassword = (user: IUser) => {
  const obj = user.toObject ? user.toObject() : { ...user };
  const { password: _password, ...safeUser } = obj as IUser & Record<string, unknown>;
  return safeUser;
};

export class UserService implements IUserService {
  constructor(private readonly repo: IUserRepository) {}

  async getProfile(userId: string) {
    const user = await this.getUser(userId);
    return withoutPassword(user);
  }

  async updateProfile(userId: string, data: UpdateUserDto) {
    const user = await this.repo.updateUser(userId, data);
    if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return withoutPassword(user);
  }

  async addAddress(userId: string, addressData: AddressDto) {
    const user = await this.getUser(userId);
    if (addressData.isDefault) {
      user.addresses.forEach((addr) => { addr.isDefault = false; });
    } else if (user.addresses.length === 0) {
      addressData.isDefault = true;
    }
    user.addresses.push(addressData as IUser["addresses"][number]);
    const updated = await this.repo.updateAddresses(userId, user.addresses);
    if (!updated) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return updated.addresses;
  }

  async updateAddress(userId: string, addressId: string, addressData: AddressDto) {
    const user = await this.getUser(userId);
    const idx = user.addresses.findIndex((a) => (a as Record<string, unknown>)._id?.toString() === addressId);
    if (idx === -1) throw new NotFoundError(Messages.ADDRESS_NOT_FOUND);
    if (addressData.isDefault && !user.addresses[idx].isDefault) {
      user.addresses.forEach((addr) => { addr.isDefault = false; });
    }
    user.addresses[idx] = { ...user.addresses[idx], ...addressData };
    const updated = await this.repo.updateAddresses(userId, user.addresses);
    if (!updated) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return updated.addresses;
  }

  async deleteAddress(userId: string, addressId: string) {
    const user = await this.getUser(userId);
    const address = user.addresses.find((a) => (a as Record<string, unknown>)._id?.toString() === addressId);
    if (!address) throw new NotFoundError(Messages.ADDRESS_NOT_FOUND);
    if (address.isDefault && user.addresses.length > 1) {
      throw new BadRequestError(Messages.CANNOT_DELETE_DEFAULT_ADDRESS);
    }
    user.addresses = user.addresses.filter((a) => (a as Record<string, unknown>)._id?.toString() !== addressId);
    const updated = await this.repo.updateAddresses(userId, user.addresses);
    if (!updated) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return updated.addresses;
  }

  async setDefaultAddress(userId: string, addressId: string) {
    const user = await this.getUser(userId);
    const address = user.addresses.find((a) => (a as Record<string, unknown>)._id?.toString() === addressId);
    if (!address) throw new NotFoundError(Messages.ADDRESS_NOT_FOUND);
    user.addresses.forEach((addr) => { addr.isDefault = false; });
    address.isDefault = true;
    const updated = await this.repo.updateAddresses(userId, user.addresses);
    if (!updated) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return updated.addresses;
  }

  async changePassword(userId: string, dto: ChangePasswordDto) {
    const user = await this.getUser(userId);
    const isMatch = await bcrypt.compare(dto.oldPassword, user.password);
    if (!isMatch) throw new BadRequestError(Messages.INCORRECT_OLD_PASSWORD);
    const hash = await bcrypt.hash(dto.newPassword, BCRYPT_SALT_ROUNDS);
    await this.repo.updatePassword(userId, hash);
    return { message: Messages.PASSWORD_UPDATED };
  }

  async sendPhoneOtp(_userId: string, phone: string) {
    const otp = generateOtp();
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);
    await this.repo.deleteOtp({ phone });
    await this.repo.createOtp({ phone, otp, expiresAt });
    logger.info(`[TESTING] Mock SMS sent to ${phone}: Your OTP is ${otp}`);
    return { message: Messages.OTP_SENT_PHONE };
  }

  async verifyPhoneOtp(userId: string, phone: string, otp: string) {
    const record = await this.repo.findOtp({ phone, otp });
    if (!record || record.expiresAt < new Date()) {
      throw new BadRequestError(Messages.OTP_INVALID_OR_EXPIRED);
    }
    await this.repo.deleteOtp({ _id: record._id });
    const user = await this.repo.updateUser(userId, { phone });
    if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return withoutPassword(user);
  }

  async sendPasswordOtp(userId: string) {
    const user = await this.getUser(userId);
    const otp = generateOtp();
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);
    await this.repo.deleteOtp({ email: user.email });
    await this.repo.createOtp({ email: user.email, otp, expiresAt });
    logger.info(`[TESTING] Mock Email sent to ${user.email}: Your OTP for password change is ${otp}`);
    return { message: Messages.OTP_SENT_EMAIL };
  }

  async verifyPasswordOtp(userId: string, otp: string, newPassword: string) {
    const user = await this.getUser(userId);
    const record = await this.repo.findOtp({ email: user.email, otp });
    if (!record || record.expiresAt < new Date()) {
      throw new BadRequestError(Messages.OTP_INVALID_OR_EXPIRED);
    }
    await this.repo.deleteOtp({ _id: record._id });
    const hash = await bcrypt.hash(newPassword, BCRYPT_SALT_ROUNDS);
    await this.repo.updatePassword(userId, hash);
    return { message: Messages.PASSWORD_UPDATED };
  }

  async sendEmailOtp(userId: string, newEmail: string) {
    const existingUser = await this.repo.findByEmail(newEmail);
    if (existingUser?._id?.toString() !== userId) {
      throw new BadRequestError(Messages.EMAIL_ALREADY_IN_USE);
    }
    const otp = generateOtp();
    const expiresAt = new Date(Date.now() + OTP_EXPIRY_MS);
    await this.repo.deleteOtp({ email: newEmail });
    await this.repo.createOtp({ email: newEmail, otp, expiresAt });
    logger.info(`[TESTING] Mock Email sent to ${newEmail}: Your OTP is ${otp}`);
    return { message: Messages.OTP_SENT_EMAIL };
  }

  async verifyEmailOtp(userId: string, newEmail: string, otp: string) {
    const existingUser = await this.repo.findByEmail(newEmail);
    if (existingUser?._id?.toString() !== userId) {
      throw new BadRequestError(Messages.EMAIL_ALREADY_IN_USE);
    }
    const record = await this.repo.findOtp({ email: newEmail, otp });
    if (!record || record.expiresAt < new Date()) {
      throw new BadRequestError(Messages.OTP_INVALID_OR_EXPIRED);
    }
    await this.repo.deleteOtp({ _id: record._id });
    const user = await this.repo.updateUser(userId, { email: newEmail });
    if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return withoutPassword(user);
  }

  private async getUser(userId: string): Promise<IUser> {
    const user = await this.repo.findById(userId);
    if (!user) throw new NotFoundError(Messages.USER_NOT_FOUND);
    return user;
  }
}

import { Request } from "express";
