import { Response, NextFunction } from "express";
import { AuthRequest } from "../interfaces/AuthRequest";
import { AppError } from "../errors/AppError";
import { Messages } from "../constants/messages";
import { StatusCodes } from "../constants/statusCodes";
import { ProviderAccountModel } from "../../models/providerAccount.model";
import { ApplicationStatus } from "../enums/application-status.enum";

/**
 * Middleware that verifies the authenticated provider has an approved account.
 * Reads provider ID directly from JWT (req.user.id = ProviderAccount._id).
 */
export const createApprovedProviderMiddleware = () =>
  async (req: AuthRequest, _res: Response, next: NextFunction): Promise<void> => {
    try {
      if (!req.user) {
        return next(new AppError(Messages.UNAUTHORIZED, StatusCodes.UNAUTHORIZED));
      }

      const provider = await ProviderAccountModel.findById(req.user.id)
        .populate("categoryId", "name icon")
        .lean();

      if (!provider || provider.applicationStatus !== ApplicationStatus.APPROVED) {
        return next(new AppError(Messages.APPLICATION_NOT_APPROVED, StatusCodes.FORBIDDEN));
      }

      (req as any).provider = provider;
      next();
    } catch (error) {
      next(error);
    }
  };

import { logger } from "../logger/logger";

export interface GeocodingResult {
  latitude: number;
  longitude: number;
  state?: string;
  district?: string;
  city?: string;
  pincode?: string;
  fullAddress?: string;
}

const NOMINATIM_BASE = "https://nominatim.openstreetmap.org";

async function nominatimFetch(url: string): Promise<any> {
  const res = await fetch(url, {
    headers: { "User-Agent": "AllServeApp/1.0" },
  });
  if (!res.ok) return null;
  return res.json();
}

// Geocode an address string (city, pincode, or full address) into coordinates.
//  Returns null if geocoding fails — caller should handle gracefully.



export async function geocodeAddress(query: string): Promise<GeocodingResult | null> {
  try {
    const data = await nominatimFetch(
      `${NOMINATIM_BASE}/search?q=${encodeURIComponent(query)}&format=json&addressdetails=1&limit=1&countrycodes=in`
    );
    if (!data?.length) return null;
    const result = data[0];
    const addr = result.address || {};
    return {
      latitude: parseFloat(result.lat),
      longitude: parseFloat(result.lon),
      state: addr.state,
      district: addr.state_district || addr.county,
      city: addr.city || addr.town || addr.village,
      pincode: addr.postcode,
      fullAddress: result.display_name,
    };
  } catch (err) {
    logger.error("Geocoding failed", { query, error: err });
    return null;
  }
}

  // Reverse geocode coordinates into address details.

export async function reverseGeocode(lat: number, lng: number): Promise<GeocodingResult | null> {
  try {
    const data = await nominatimFetch(
      `${NOMINATIM_BASE}/reverse?lat=${lat}&lon=${lng}&format=json&addressdetails=1`
    );
    if (!data || data.error) return null;
    const addr = data.address || {};
    return {
      latitude: lat,
      longitude: lng,
      state: addr.state,
      district: addr.state_district || addr.county,
      city: addr.city || addr.town || addr.village,
      pincode: addr.postcode,
      fullAddress: data.display_name,
    };
  } catch (err) {
    logger.error("Reverse geocoding failed", { lat, lng, error: err });
    return null;
  }
}
